(()=>{
'use strict';
const G=window.Game,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const line=(speaker,text)=>`<p class="line"><b>${esc(speaker||'서술')}</b>${esc(text)}</p>`;
function fresh(c){const s=G.fresh(document.querySelector('#reader-name').value||'이웃');s.turn=c.hours[0];s.money=100000;return s;}
function sceneText(s){const sc=s.scene;let out=sc.lines.map(([who,text])=>line(who,text)).join('');
if(sc.options?.length)out+='<h4>선택지와 이어지는 반응</h4>'+sc.options.map((o,i)=>{const copy=JSON.parse(JSON.stringify(s));copy.scene.step=copy.scene.lines.length;G.choose(copy,i);return `<div class="option">${line('주인공의 선택',o.text)}${sc.addressPrompt?sceneText(copy):copy.scene.lines.map(([who,text])=>line(who,text)).join('')}</div>`;}).join('');return out;}
function episode(c,e,n){const echoes=Array.isArray(e[7])?e[7]:e[7]?[e[7]]:[];const variant=window.STORY_VARIANTS?.[c.id]?.[n];const refs=[...new Set([...echoes.map(x=>x.at),...(variant?[variant.at]:[])])];
let paths=[[]];for(const at of refs)paths=paths.flatMap(p=>[4,5].map(k=>[...p,{at,choice:c.events[at][k]}]));
return `<article><h3>${n+1}화 · ${esc(e[0])}</h3>`+paths.flatMap(path=>(c.id==='honey'&&n>4?['formal','casual']:[null]).map(mode=>({path,mode}))).map(({path,mode})=>{const s=fresh(c);if(mode)s.honeyAddress=mode;s.progress[c.id]=n;for(const p of path)s.choices[c.id][p.at]=p.choice[1];if(!G.visit(s,c.id))throw Error(`장면 불러오기 실패: ${c.id}/${n}`);return `<div class="${path.length?'branch':''}">${path.length?`<p class="condition">이전 선택: ${path.map(p=>`${p.at+1}화 「${esc(p.choice[0])}」`).join(' / ')}</p>`:''}${mode?`<p class="condition">호칭: ${mode==='casual'?'편하게 부르기 허용':'존칭 유지'}</p>`:''}${sceneText(s)}</div>`;}).join('')+'</article>';}
function member(c){let out=`<section id="${c.id}"><h2>${esc(c.name)}</h2>`+c.events.map((e,n)=>episode(c,e,n)).join('');
out+='<h3>외출 / 데이트</h3>';c.outings.forEach((o,n)=>{for(const mode of c.id==='honey'?['formal','casual']:[null]){const s=fresh(c);if(mode)s.honeyAddress=mode;s.progress[c.id]=8;s.dates[c.id]=n;if(!G.outing(s,c.id))throw Error('외출 불러오기 실패');out+=`<h4>${n+1}. ${esc(o[0])}${mode?' · '+(mode==='casual'?'편한 호칭':'존칭'):''}</h4>`+sceneText(s);}});
const gift=window.GIFT_MEMORIES[c.id];out+=`<h3>기억한 선물 · ${esc(gift.name)}</h3><p class="condition">이 말을 실제로 들은 뒤 수첩에 기록됩니다.</p>${line(c.name,gift.quote)}${(c.id==='honey'?['formal','casual']:[null]).map(mode=>line('선물을 받은 반응'+(mode?' · '+(mode==='casual'?'편한 호칭':'존칭'):''),G.formatText(fresh(c),mode?window.ADDRESSING_HONEY[mode].giftReply:gift.reply))).join('')}`;
for(const name of c.id==='siho'?['여보','오빠']:[null]){for(const mode of c.id==='honey'?['formal','casual']:[null]){const pages=G.endingPages({...fresh(c),honeyAddress:mode||undefined,ending:{id:c.id,kind:'good',petName:name}});out+=`<h3>연애 결말${name?' · '+esc(name)+' 선택':''}${mode?' · '+(mode==='casual'?'편한 호칭':'존칭'):''}</h3>`+pages.map(p=>`<h4>${esc(p[1])}</h4>${line('',p[2])}`).join('');}}
const normal=G.endingInfo({...fresh(c),ending:{id:c.id,kind:'normal'}});return out+`<h3>우정 결말 · ${esc(normal[0])}</h3>${line('',normal[1])}</section>`;}
window.ScriptReader={member,episode};
const select=document.querySelector('#member');select.insertAdjacentHTML('beforeend',CAST.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join(''));
function render(){const list=select.value==='all'?CAST:CAST.filter(c=>c.id===select.value);document.querySelector('#nav').innerHTML=list.map(c=>`<a href="#${c.id}">${esc(c.name)}</a>`).join('');document.querySelector('#script').innerHTML=list.map(member).join('')+(select.value==='all'?'<h2>혼자 맞는 결말</h2>'+line('',G.endingInfo({ending:{id:'solo',kind:'normal'}})[1]):'');}
document.querySelector('#reader-name').addEventListener('input',render);select.addEventListener('change',render);document.querySelector('#print').addEventListener('click',()=>window.print());render();
})();